namespace {
constexpr auto base="/home/we6jbo/Projects/AncesTale/lib/";
constexpr auto failure="Certificate error: please cp /opt/JSLib-dont-delete/ to /home/we6jbo/Projects/AncesTale/lib/";
using open_t=void*(*)(const char*);
using count_t=int(*)(void*);
using list_t=char*(*)(void*,int,int);
using free_t=void(*)(void*);
using close_t=void(*)(void*);

bool verifyFile(const QString& dataFile,const QString& signatureFile,const QByteArray& publicPem){
  BIO* b=BIO_new_mem_buf(publicPem.constData(),static_cast<int>(publicPem.size()));
  if(!b)return false;
  EVP_PKEY* key=PEM_read_bio_PUBKEY(b,nullptr,nullptr,nullptr);BIO_free(b);
  if(!key)return false;
  EVP_MD_CTX* ctx=EVP_MD_CTX_new();
  bool ok=false;
  QFile sf(signatureFile),df(dataFile);
  if(ctx && sf.open(QIODevice::ReadOnly) && df.open(QIODevice::ReadOnly)){
    QByteArray sig=sf.readAll();
    if(EVP_DigestVerifyInit(ctx,nullptr,EVP_sha256(),nullptr,key)==1){
      bool valid=true;
      while(!df.atEnd()){
        QByteArray b=df.read(64*1024);
        if(b.isEmpty() || EVP_DigestVerifyUpdate(ctx,b.constData(),size_t(b.size()))!=1){valid=false;break;}
      }
      if(valid)ok=(EVP_DigestVerifyFinal(ctx,reinterpret_cast<const unsigned char*>(sig.constData()),size_t(sig.size()))==1);
    }
  }
  EVP_MD_CTX_free(ctx);EVP_PKEY_free(key);return ok;
}
}
MainWindow::MainWindow(QWidget* parent):QMainWindow(parent){
  setWindowTitle("AncesTale HVZA signed genealogy viewer");resize(1100,650);
  auto* container=new QWidget(this);auto* layout=new QVBoxLayout(container);
  auto* status=new QLabel(container);layout->addWidget(status);
  table_=new QTableWidget(container);table_->setColumnCount(6);
  table_->setHorizontalHeaderLabels({"ID","Name","TG codes","Website","Updated","Data JSON"});
  table_->horizontalHeader()->setStretchLastSection(true);
  layout->addWidget(table_);setCentralWidget(container);
  const QString dir=QString::fromUtf8(base);
  const QString flag="/home/we6jbo/Projects/AncesTale/error-cert-does-not-match.txt";
  if(QFile::exists(flag)){
    qCritical().noquote()<<"ERROR Public certificate was altered: "<<flag;
    status->setText("ERROR Public certificate was altered. Restore your trusted certificate and rerun the boot check.");return;
  }
  QFile cert(dir+"hvza-public.pem");
  if(!cert.open(QIODevice::ReadOnly)){
    qCritical().noquote()<<failure;status->setText(failure);return;
  }
  const QByteArray pem=cert.readAll();
  const QByteArray digest=QCryptographicHash::hash(pem,QCryptographicHash::Sha256).toHex();
  if(digest != QByteArray(HVZA_PINNED_CERT_SHA256)){
    qCritical().noquote()<<"ERROR Public certificate was altered";
    status->setText("ERROR Public certificate was altered");return;
  }
  if(!verifyFile(dir+"libhvza.so",dir+"libhvza.so.sig",pem)
      || !verifyFile(dir+"story.db",dir+"story.db.sig",pem)){
    qCritical().noquote()<<failure;status->setText(failure);return;
  }
  // Never load unverified shared library bytes.
  QLibrary dll(dir+"libhvza.so");
  if(!dll.load()) {qCritical().noquote()<<dll.errorString();status->setText(dll.errorString());return;}
  auto open=reinterpret_cast<open_t>(dll.resolve("hvza_open"));
  auto count=reinterpret_cast<count_t>(dll.resolve("hvza_count"));
  auto list=reinterpret_cast<list_t>(dll.resolve("hvza_list"));
  auto release=reinterpret_cast<free_t>(dll.resolve("hvza_free"));
  auto close=reinterpret_cast<close_t>(dll.resolve("hvza_close"));
  if(!open||!count||!list||!release||!close){status->setText("ERROR: library API missing");return;}
  void* db=open((dir+"story.db").toUtf8().constData());
  if(!db){status->setText("ERROR: cannot open signed database");return;}
  int n=count(db);
  if(n>=0 && n<=100000){
    char* raw=list(db,0,n);
    if(raw){
      const auto doc=QJsonDocument::fromJson(raw);release(raw);
      if(doc.isArray()){
        const QJsonArray records=doc.array();table_->setRowCount(records.size());
        for(int r=0;r<records.size();++r){
          const auto p=records[r].toObject();
          const QStringList fields={QString::number(p.value("id").toInt()),p.value("display_name").toString(),
            p.value("tg_codes").toString(),p.value("website").toString(),p.value("updated_at").toString(),p.value("data_json").toString()};
          for(int c=0;c<fields.size();++c)table_->setItem(r,c,new QTableWidgetItem(fields[c]));
        }
        status->setText(QString("Verified signature and displayed %1 records").arg(records.size()));
      }
    }
  }
  close(db);
}
